25	std::optional<std::pair<std::string, std::string>> ResourceTable::ParseRouteEdge(
26	    const std::string& resource_id) {
27	  const std::string prefix = "route_edge:";
28	  if (!StartsWith(resource_id, prefix)) {
29	    return std::nullopt;
30	  }
31	  const auto separator = resource_id.find("__", prefix.size());
32	  if (separator == std::string::npos) {
33	    return std::nullopt;
34	  }
35	  const auto first = resource_id.substr(prefix.size(), separator - prefix.size());
36	  const auto second = resource_id.substr(separator + 2);
37	  if (first.empty() || second.empty()) {
38	    return std::nullopt;
39	  }
40	  return std::make_pair(first, second);
41	}
