47	std::vector<std::string> ResourceTable::BuildLockIds(
48	    const std::vector<std::string>& station_path, const bool include_intersection_locks) {
49	  std::vector<std::string> lock_ids;
50	  if (include_intersection_locks) {
51	    for (const auto& station_id : station_path) {
52	      lock_ids.push_back(RouteNodeId(station_id));
53	    }
54	  }
55	  for (std::size_t index = 1; index < station_path.size(); ++index) {
56	    lock_ids.push_back(RouteEdgeId(station_path[index - 1], station_path[index]));
57	  }
58	  return lock_ids;
59	}
