68	  for (const auto& resource_id : resource_ids) {
69	    const auto existing = locks_.find(resource_id);
70	    if (existing != locks_.end() && existing->second != mission_id) {
71	      std::ostringstream oss;
72	      oss << "resource locked: " << resource_id << " by " << existing->second;
73	      result.message = oss.str();
74	      return result;  // 未落任何锁，原子性成立
75	    }
76	  }
77	  for (const auto& resource_id : resource_ids) {
78	    locks_[resource_id] = mission_id;
79	    result.newly_reserved.push_back(resource_id);
80	  }
81	  std::ostringstream oss;
82	  oss << "reserved " << resource_ids.size() << " resource(s)";
83	  result.success = true;
84	  result.message = oss.str();
85	  return result;
86	}
