9	DeadlockDetector::DeadlockDetector(DeadlockDetectorConfig config)
10	    : config_(config) {}
11	
12	std::vector<std::vector<std::string>> DeadlockDetector::DetectCycles(
13	    const ResourceAllocationModel& wfg_model) const {
14	  std::vector<std::vector<std::string>> cycles;
15	
16	  // 1. 构建任务等待图 (Wait-For Graph)：
17	  // 任务 M1 等待资源 R，而 R 当前被 M2 持有 -> 有向边 M1 -> M2，并记下触发该边的资源
18	  //（环路径要以 waiter -> resource -> holder 交替记录）。
19	  // 同一 (等待者, 持有者) 只建一条边：多把锁指向同一持有者时不重复上报同一环，
20	  // 与改前 std::set 去重语义一致。
21	  struct WaitEdge {
22	    std::string holder;
23	    std::string resource_id;
24	  };
25	  std::unordered_map<std::string, std::vector<WaitEdge>> adj;
26	  for (const auto& [waiter_m, requested_resources] : wfg_model.waiting_for) {
27	    for (const auto& res_id : requested_resources) {
28	      auto it = wfg_model.held_by.find(res_id);
29	      if (it == wfg_model.held_by.end() || it->second == waiter_m) {
30	        continue;
31	      }
32	      auto& edges = adj[waiter_m];
33	      const bool duplicated =
34	          std::any_of(edges.begin(), edges.end(),
35	                      [&it](const WaitEdge& edge) { return edge.holder == it->second; });
36	      if (!duplicated) {
37	        edges.push_back(WaitEdge{it->second, res_id});
38	      }
39	    }
40	  }
41	
42	  // 2. 使用 DFS 进行拓扑三色标记法或路径回溯检测有向图环
43	  // 0: 未访问, 1: 正在当前递归栈中 (在探索), 2: 已完成探索
44	  // path 只记任务节点；path_res[i] 记 path[i] -> path[i+1] 所等待的资源。
45	  std::unordered_map<std::string, int> visit_state;
46	  std::vector<std::string> path;
47	  std::vector<std::string> path_res;
48	
49	  auto dfs = [&](auto& self, const std::string& u) -> void {
50	    visit_state[u] = 1;
51	    path.push_back(u);
52	
53	    auto it = adj.find(u);
54	    if (it != adj.end()) {
55	      for (const auto& edge : it->second) {
56	        const std::string& v = edge.holder;
57	        if (visit_state[v] == 1) {
58	          // 找到环！自栈上 v 起提取到当前 u，段间用 path_res 的资源，
59	          // 末段用回边 (u -> v) 的资源并闭合回 v：
60	          //   [v, res, ..., u, res, v] —— 任务与资源交替，死锁可视化的
61	          //   deadlocked_nodes 由其中的 route_edge:/route_node: 项解析而来。
62	          const auto cycle_start = std::find(path.begin(), path.end(), v);
63	          if (cycle_start != path.end()) {
64	            const auto start_index =
65	                static_cast<std::size_t>(std::distance(path.begin(), cycle_start));
66	            std::vector<std::string> cycle;
67	            for (std::size_t index = start_index; index < path.size(); ++index) {
68	              cycle.push_back(path[index]);
69	              cycle.push_back(index + 1 < path.size() ? path_res[index]
70	                                                      : edge.resource_id);
71	            }
72	            cycle.push_back(path[start_index]);  // 闭合回起始任务
73	            cycles.push_back(cycle);
74	          }
75	        } else if (visit_state[v] == 0) {
76	          path_res.push_back(edge.resource_id);
77	          self(self, v);
78	          path_res.pop_back();
79	        }
80	      }
81	    }
82	
83	    path.pop_back();
84	    visit_state[u] = 2;
85	  };
86	
87	  // 起点按字典序遍历：同一张图的环报告次序可复现（unordered_map 顺序不稳定）
88	  std::vector<std::string> start_nodes;
89	  start_nodes.reserve(adj.size());
90	  for (const auto& [node, _] : adj) {
91	    start_nodes.push_back(node);
92	  }
93	  std::sort(start_nodes.begin(), start_nodes.end());
94	  for (const auto& node : start_nodes) {
95	    if (visit_state[node] == 0) {
96	      dfs(dfs, node);
97	    }
98	  }
99	
100	  return cycles;
101	}
102	
103	std::vector<DeadlockFinding> DeadlockDetector::Detect(
104	    const DeadlockSnapshot& snapshot) const {
105	  std::vector<DeadlockFinding> findings;
106	  const auto now = std::chrono::steady_clock::now();
107	
108	  // 1. 【严密图论判定】通过 Wait-For Graph 进行 0 毫秒确定性死锁环检测
109	  const auto cycles = DetectCycles(snapshot.allocation_graph);
110	  for (const auto& cycle : cycles) {
111	    DeadlockFinding f;
112	    f.kind = DeadlockKind::kMutualBlock;
113	    f.cycle_path = cycle;
114	    // cycle_path 为任务/资源交替且首尾闭合：偶数位是任务，奇数位是资源，
115	    // mission_ids 只取任务（recovery 据此对任务下发暂停/取消，不能混入资源 id）
116	    for (std::size_t i = 0; i + 1 < cycle.size(); i += 2) {
117	      f.mission_ids.push_back(cycle[i]);
118	    }
119	    std::string desc = "Wait-For Graph Cycle detected: [";
120	    for (size_t i = 0; i < cycle.size(); ++i) {
121	      desc += cycle[i];
122	      if (i + 1 < cycle.size()) desc += " -> ";
123	    }
124	    desc += "]";  // cycle_path 自身闭合回起始任务
125	    f.description = desc;
126	    findings.push_back(std::move(f));
127	  }
128	
129	  // 2. 启发式活跃任务过多检测
130	  if (config_.max_active_missions > 0 &&
131	      snapshot.active_missions.size() > config_.max_active_missions) {
132	    DeadlockFinding f;
133	    f.kind = DeadlockKind::kMutualBlock;
134	    f.description = "too many active missions: " +
135	                    std::to_string(snapshot.active_missions.size());
136	    for (const auto& m : snapshot.active_missions) {
137	      f.mission_ids.push_back(m.id);
138	    }
139	    findings.push_back(std::move(f));
140	  }
141	
142	  // 3. 启发式：ACTIVE 但无 progress 超过阈值
143	  for (const auto& m : snapshot.active_missions) {
144	    auto it = snapshot.last_progress.find(m.id);
145	    if (it == snapshot.last_progress.end()) {
146	      continue;
147	    }
148	    if (now - it->second > config_.active_idle_threshold) {
149	      DeadlockFinding f;
150	      f.kind = DeadlockKind::kIdleActive;
151	      f.description = "mission idle too long: " + m.id;
152	      f.mission_ids.push_back(m.id);
153	      findings.push_back(std::move(f));
154	    }
155	  }
156	
157	  // 4. 启发式：长期持锁检测
158	  std::unordered_map<std::string, std::vector<std::string>> resource_to_missions;
159	  for (const auto& m : snapshot.active_missions) {
160	    if (!m.reservation_id.empty()) {
161	      resource_to_missions[m.reservation_id].push_back(m.id);
162	    }
163	  }
164	  for (const auto& [resource, acquired_at] : snapshot.reservation_acquired_at) {
165	    if (now - acquired_at <= config_.reservation_hold_threshold) {
166	      continue;
167	    }
168	    auto it = resource_to_missions.find(resource);
169	    if (it == resource_to_missions.end() || it->second.empty()) {
170	      continue;
171	    }
172	    DeadlockFinding f;
173	    f.kind = DeadlockKind::kLongReservationHold;
174	    f.description = "resource held too long: " + resource;
175	    f.mission_ids = it->second;
176	    findings.push_back(std::move(f));
177	  }
178	
179	  return findings;
180	}
181	
182	}  // namespace amr_dispatcher_core::dispatcher
