#pragma once

#include <cmath>
#include <string>
#include <vector>

namespace amr_dispatcher_core {

struct Point2D {
  double x{0.0};
  double y{0.0};
};

struct Pose2D {
  double x{0.0};
  double y{0.0};
  double theta{0.0};  // 航向角 (rad), 范围 [-M_PI, M_PI]
};

/**
 * @brief 路径规划器抽象基类 (IoC 控制反转接口)
 * 调度系统与业务核心仅依赖此纯虚接口，不依赖任何具体的图搜索、几何或数值优化算法。
 * 留出标准扩展插槽，未来可派生实现 A*、Hybrid A*、Nav2 插件等。
 */
class IPathPlanner {
 public:
  virtual ~IPathPlanner() = default;

  /**
   * @brief 在起点与终点之间规划离散二维路径点序列
   * @param start 起点二维位姿 (x, y, theta)
   * @param goal 终点二维位姿 (x, y, theta)
   * @param edge_id 可选的拓扑边编号，供基于图先验规划使用
   * @return std::vector<Pose2D> 生成的路径序列；若规划失败返回空序列
   */
  virtual std::vector<Pose2D> Plan(const Pose2D& start, const Pose2D& goal,
                                   const std::string& edge_id = "") = 0;

  /**
   * @brief 获取规划器实现名称
   */
  virtual std::string GetPlannerName() const = 0;
};

}  // namespace amr_dispatcher_core
#pragma once

#include <string>
#include <vector>

#include "amr_dispatcher_core/planning/path_planner_interface.hpp"

namespace amr_dispatcher_core::path_tracking {

struct TwistCommand {
  double linear_x{0.0};          // 期望线速度 (m/s)
  double angular_z{0.0};         // 期望角速度 (rad/s)
  bool reached_goal{false};      // 是否已到达目标点
  double cross_track_error{0.0}; // 横向跟踪误差 (m)
  double heading_error{0.0};     // 航向角误差 (rad)
};

/**
 * @brief 路径跟踪控制器抽象基类 (IoC 控制反转接口)
 * 无论底盘是使用纯几何前视 Pure Pursuit、Stanley，还是未来的 MPC / LQR，
 * 节点与上层逻辑均面向此抽象接口交互。
 */
class IPathTracker {
 public:
  virtual ~IPathTracker() = default;

  /**
   * @brief 设置或更新待跟踪路径
   */
  virtual void SetPath(std::vector<amr_dispatcher_core::Pose2D> path) = 0;

  /**
   * @brief 清空当前跟踪路径
   */
  virtual void ClearPath() = 0;

  /**
   * @brief 是否持有有效目标路径
   */
  virtual bool HasPath() const = 0;

  /**
   * @brief 根据机器人当前位姿解算速度控制指令
   */
  virtual TwistCommand ComputeControl(const amr_dispatcher_core::Pose2D& current_pose) const = 0;

  /**
   * @brief 获取控制器名称
   */
  virtual std::string GetTrackerName() const = 0;
};

}  // namespace amr_dispatcher_core::path_tracking
